import{z as B,x as s,o as t,c as p,q as n,j as A,D as E,d as l,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"做空规则与报升","description":"","frontmatter":{"title":"做空规则与报升","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/short-sale-uptick.md","filePath":"quant/short-sale-uptick.md","lastUpdated":1791063341000}'),d={name:"quant/short-sale-uptick.md"};function D(u,a,h,c,m,C){const r=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="做空规则与报升" tabindex="-1">做空规则与报升 <a class="header-anchor" href="#做空规则与报升" aria-label="Permalink to &quot;做空规则与报升&quot;">​</a></h1><div class="epigraph"><p>可借且未停牌，仍可能不能按你想要的方式卖空：报升、融券限制与临时空头禁令把空头腿从「负权重」变成受规则约束的委托。</p><footer>—— 据 SEC Regulation SHO；Diether, Lee and Werner 对报升的研究；Beber and Pagano 对空头限制的讨论整理</footer></div><p>上一课<a href="/quant/halt-limit-backtest">停牌与涨跌停对回测</a>给出可成交集合。做空还要过交易规则：报升（uptick）、价格测试、裸卖空限制、以及危机中的临时禁令。本课补空头委托如何合法发出。借券资格已在融券课；本课是成交方式。不把 SHO 写成法条注释。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纸面多空每天按收盘把权重写成负数，隐含你总能以收盘价卖空。Regulation SHO 一类规则要求空头在全国最优买价之上或以买价且满足条件成交，危机中还有过更硬的报升。禁令期间某些金融股不能新开空头，只能回补。Beber–Pagano 讨论空头限制对流动性与价格发现的影响；回测要的是更窄的一句：当时若禁止或限制，纸面空头收益不可得。缺口是给空头委托一个<strong>规则过滤器</strong>，与可借、未停牌并列。</p><p>用今日已废止或已放宽的规则回填历史，或反过来用历史上的硬报升约束今天的美股回测而不声明，都会错。规则是时间序列。</p><p><span class="marginnote">常见误区：初学者容易拿今天的规则清单跑全历史回测。2005 年 Regulation SHO 落地前后测试口径不同，2008 年危机中多国还临时禁止金融股卖空；规则参数必须按日期切换，否则同一只股票在 2007 年与 2009 年的可空性被错误地一视同仁。</span></p><h3 id="报升不是借券费" tabindex="-1">报升不是借券费 <a class="header-anchor" href="#报升不是借券费" aria-label="Permalink to &quot;报升不是借券费&quot;">​</a></h3><p>借券费是持有成本；报升是成交约束，可能让你在急跌时无法按市价开空，只能排队或放弃。急跌恰好是纸面空头想成交的时刻。把报升当成多付几个基点，会低估：它改的是能否成交，不是费率表。</p><p><span class="marginnote">术语翻译：报升（uptick）指卖空成交价不得低于最近一次不同价格成交、或必须满足按买价成交等条件——直觉上就是「跌势里不许空头踩着下行的梯子加仓」，目的是给价格发现踩一脚刹车。</span></p><p><span class="marginnote">裸卖空限制要求先借到或定位到券再卖。这把融券课的资格与本课的委托顺序绑在一起：没有 locate 就不能发单。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开空前检查：当时规则是否允许、是否需报升或价格测试、是否在禁令名单。不允许则当日空头增量视为零，已有空头按规则或可回补。回测成交价不得劣于规则允许集；若日线无法模拟测试，至少在下跌日对空头开仓施加惩罚或禁止市价开空。禁令名单必须 PIT：用事后「曾被禁」的股票集合回填整个样本，会把未禁时期也当成不可空。</p><p>空头回补（买开平）通常不受报升限制，但受涨跌停与停牌限制。不要把开空规则套到回补上。</p>',14)),(t(),A(o,null,{default:E(()=>[i(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHORT%5B%22%E7%A9%BA%E5%A4%B4%E6%84%8F%E5%9B%BE%22%5D%20--%3E%20BORROW%5B%22%E5%8F%AF%E5%80%9F%22%5D%0A%20%20BORROW%20--%3E%20HALT%5B%22%E6%9C%AA%E5%81%9C%E7%89%8C%E5%8F%AF%E5%8D%96%22%5D%0A%20%20HALT%20--%3E%20RULE%5B%22%E6%8A%A5%E5%8D%87%E6%88%96%E7%A6%81%E4%BB%A4%22%5D%0A%20%20RULE%20--%3E%20FILL%5B%22%E5%90%88%E6%B3%95%E6%88%90%E4%BA%A4%22%5D%0A%20%20NEG%5B%22%E6%94%B6%E7%9B%98%E8%B4%9F%E6%9D%83%E9%87%8D%22%5D%20--%3E%20BIAS%5B%22%E5%BF%BD%E7%95%A5%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"价格测试在下跌日绑定：你最想开空的时候规则最紧。日频回测无法逐笔模拟时，保守做法是下跌日禁止新开空、只允许持有或回补，并报告因此损失的纸面收益。这比假装以收盘价空出更接近可实施集合。临时禁令按名单与生效日过滤，未列入的名字保持可空，不要把整个金融行业在禁令年一律删掉。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"空头限制在下跌日绑定：价格发现变慢、反弹时挤压更猛，纸面空头在限制日「成交」的那一段往往最不可实施。与质量、PEAD 空头叠加时，三次过滤（可借、可成交、可报升）之后，剩余截面偏向大盘 GC 券，异象衰减。这不是要你放弃空头，而是禁止把未过滤的空头收益写成可交易 alpha。",-1)),(t(),A(o,null,{default:E(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20O%5B%22%E5%BD%93%E6%97%A5%E8%AE%A2%E5%8D%95%E6%84%8F%E5%9B%BE%22%5D%20--%3E%20K%7B%22%E5%BC%80%E6%96%B0%E7%A9%BA%20%E8%BF%98%E6%98%AF%20%E5%9B%9E%E8%A1%A5%3F%22%7D%0A%20%20K%20--%3E%7C%22%E5%9B%9E%E8%A1%A5%22%7C%20G3%5B%22%E4%B8%8D%E5%8F%97%E6%8A%A5%E5%8D%87%E7%BA%A6%E6%9D%9F%20%E4%BD%86%E5%8F%97%E6%B6%A8%E8%B7%8C%E5%81%9C%E4%B8%8E%E5%81%9C%E7%89%8C%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20K%20--%3E%7C%22%E5%BC%80%E6%96%B0%E7%A9%BA%22%7C%20G1%5B%22%E9%97%A81%3A%20%E5%B7%B2%20locate%20%E5%8F%AF%E5%80%9F%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E9%97%A82%3A%20%E6%9C%AA%E5%81%9C%E7%89%8C%E5%8F%AF%E5%8D%96%22%5D%0A%20%20G2%20--%3E%20G3U%5B%22%E9%97%A83%3A%20%E6%8A%A5%E5%8D%87%E6%88%96%E4%BB%B7%E6%A0%BC%E6%B5%8B%E8%AF%95%20%E4%B8%94%E4%B8%8D%E5%9C%A8%E7%A6%81%E4%BB%A4%E5%90%8D%E5%8D%95%22%5D%0A%20%20G3U%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20F%5B%22%E6%8C%89%E8%A7%84%E5%88%99%E5%85%81%E8%AE%B8%E7%9A%84%E4%BB%B7%E6%A0%BC%E6%88%90%E4%BA%A4%22%5D%0A%20%20G3U%20--%3E%7C%22%E4%B8%8D%E9%80%9A%E8%BF%87%22%7C%20X%5B%22%E5%BD%93%E6%97%A5%E7%A9%BA%E5%A4%B4%E5%A2%9E%E9%87%8F%E8%AE%B0%E9%9B%B6%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：假设纸面空头腿十年年化贡献 3%，其中约四成落在规则最紧的急跌日；按「下跌日禁止新开空」过滤后，真实可实施的贡献可能只剩 2% 上下。这段过滤差必须写进报告，而不是当成「滑点」一笔带过。</span></p><p><span class="marginnote">下一课期权行权会创造临时空头（指派）；规则同样适用于因行权产生的股票空头，不能只过滤主动开空。</span></p><p>开空增量过三道门：可借、可卖、当时价格测试或禁令。禁令名单按生效日 PIT。下跌日若无法模拟逐笔报升，至少禁止空头市价开仓或施加成交惩罚。回补不受报升约束，但受涨跌停约束。规则参数按历史时段切换：SHO 实施前后、临时禁令期、现行替代规则不得混用一个过滤器。过滤前后空头收益差要报告。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不对照各国空头禁令年表做监管综述。期权与期货的空头规则不同，下一课起分产品日历。后课默认：负权重先过当时做空规则；规则参数按日 PIT。</p><p>后课期权指派可能被动制造股票空头，同样过这三道门。本课规则参数按时段 PIT。下跌日纸面空头最不可实施，过滤差必须报告。回补与开空不对称。禁令名单不得用「曾被禁」回填未禁时期。</p><p>后课默认负权重先过当时做空规则，规则参数按日 PIT；回补与开空的约束不对称。</p><p>locate 与报升是顺序关系：没有 locate 不能发空单，有 locate 仍可能过不了价格测试。回测把两道门写成短路逻辑，不要合成一个「空头摩擦基点」去减收益——那会在下跌日假装已经成交。</p><p>因期权指派被动产生的股票空头，同样要过可借与报升两道门，不能只过滤主动开空。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可借、可成交、可合法报空是三道门。</li><li>报升约束成交方式，不是又一项借券费。</li><li>禁令与测试规则是时间序列，禁止用现行规则回填。</li><li>下跌日的纸面空头成交最不可实施。</li><li>回补与开空的规则不对称。</li><li>出处：SEC Regulation SHO；Diether, Lee and Werner；Beber and Pagano。</li></ul>',11))])}const T=B(d,[["render",D]]);export{f as __pageData,T as default};
